192	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
193	type BalanceView struct {
194		Account string `json:"account"`
195		Asset   string `json:"asset"`
196		Balance int64  `json:"balance"`
197	}
198	
199	// Snapshot 是账本查询结果。Refunds 按退款成功先后排列，无退款时为空列表。
200	type Snapshot struct {
201		Balances    []BalanceView  `json:"balances"`
