299	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
300	func (s *ledgerState) MarshalJSON() ([]byte, error) {
301		settlements := s.Settlements
302		if settlements == nil {
303			settlements = []Record{}
304		}
305		doc := unsignedDoc{
306			Version:     s.Version,
307			Initial:     balanceList(s.Initial),
308			Balances:    balanceList(s.Balances),
309			Settlements: settlements,
310			Refunds:     s.Refunds, // nil 时因 omitempty 省略，保持无退款账本的旧格式
311		}
312		payload, err := json.Marshal(doc)
313		if err != nil {
314			return nil, err
315		}
316		sum := checksumHex(payload)
317		out := make([]byte, 0, len(payload)+len(sum)+16)
318		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
319		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
320		return out, nil
321	}
322	
323	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
324	func (s *ledgerState) UnmarshalJSON(data []byte) error {
325		var doc signedDoc
326		if err := json.Unmarshal(data, &doc); err != nil {
327			return err
328		}
329		if doc.Checksum == "" {
330			return ledgerError(ErrCorrupt, "missing checksum")
331		}
332		payload, err := json.Marshal(doc.unsignedDoc)
333		if err != nil {
334			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
335		}
336		if got := checksumHex(payload); got != doc.Checksum {
337			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
338		}
339		if doc.Version != ledgerVersion {
340			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
341		}
342		initial, err := balanceMap(doc.Initial)
343		if err != nil {
344			return err
345		}
346		current, err := balanceMap(doc.Balances)
347		if err != nil {
348			return err
349		}
350		records := doc.Settlements
351		if records == nil {
352			records = []Record{}
353		}
354		refunds := doc.Refunds // 旧版账本缺省该字段，nil 视为空列表
355		if refunds == nil {
356			refunds = []RefundRecord{}
357		}
358		if err := validateAndReplay(initial, current, records, refunds); err != nil {
359			return err
360		}
361		s.Version = doc.Version
362		s.Initial = initial
363		s.Balances = current
364		s.Settlements = records
365		s.Refunds = refunds
366		return nil
367	}
368	
369	func decodeState(data []byte) (*ledgerState, error) {
370		var state ledgerState
371		if err := json.Unmarshal(data, &state); err != nil {
372			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
373				return nil, err
374			}
375			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
376		}
377		return &state, nil
378	}
379	
380	// canonicalLedgerPath 把绝对路径解析为账本的规范路径：解析目录与文件本身
381	// 的符号链接，使同一账本经不同路径（如指向账本所在目录的软链接）打开时
382	// 共享同一注册表项、同一份内存状态与互斥锁。账本文件尚不存在时（未初始化）
383	// 解析其父目录；父目录也无法解析时退回原路径。
384	func canonicalLedgerPath(abs string) string {
385		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
386			return resolved
387		}
388		if resolved, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
389			return filepath.Join(resolved, filepath.Base(abs))
390		}
391		return abs
392	}
393	
394	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
395	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
396	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
397	func CreateLedger(path string, init []BalanceInit) error {
398		if err := validateInitial(init); err != nil {
399			return err
400		}
401		abs, err := filepath.Abs(path)
402		if err != nil {
403			return ledgerError(ErrStorage, "resolve path: %v", err)
404		}
405		abs = canonicalLedgerPath(abs)
406	
407		openMu.Lock()
408		defer openMu.Unlock()
409	
410		if _, err := os.Stat(abs); err == nil {
411			return ledgerError(ErrExists, "ledger already exists at %s", abs)
412		} else if !errors.Is(err, os.ErrNotExist) {
413			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
414		}
415		if openRegistry[abs] != nil {
416			return ledgerError(ErrExists, "ledger is already initialized in this process")
417		}
418	
419		state := &ledgerState{
420			Version:     ledgerVersion,
421			Initial:     make(map[balanceKey]int64, len(init)),
422			Balances:    make(map[balanceKey]int64, len(init)),
423			Settlements: []Record{},
424			Refunds:     []RefundRecord{},
425		}
426		for _, b := range init {
427			k := balanceKey{b.Account, b.Asset}
428			state.Initial[k] = b.Balance
429			state.Balances[k] = b.Balance
430		}
431		if err := atomicWrite(abs, state); err != nil {
432			return err
433		}
434		openRegistry[abs] = &registryEntry{state: state}
435		return nil
436	}
437	
438	func validateInitial(init []BalanceInit) error {
439		seen := map[balanceKey]bool{}
440		for i, b := range init {
441			if b.Account == "" {
442				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
443			}
444			if b.Asset == "" {
445				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
446			}
447			if b.Balance < 0 {
448				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
449			}
450			k := balanceKey{b.Account, b.Asset}
451			if seen[k] {
452				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
453			}
454			seen[k] = true
455		}
456		return nil
457	}
458	
459	// Ledger 是一个可持久化的本地账本。同一进程内指向同一账本文件的多次 Open
460	// （包括经目录软链接的不同路径）返回共享同一状态与互斥锁的实例，
461	// 因此并发提交按同一本账本串行化。
462	type Ledger struct {
463		path string
464		reg  *registryEntry
465		open bool
466	}
467	
468	type registryEntry struct {
469		mu       sync.Mutex // 保护 state；整个批次串行持有
470		state    *ledgerState
471		refs     int        // 打开的句柄数
472		ops      int        // 正在执行的 Submit/Query 数
473		failHook FailWriter // 仅测试注入
474	}
475	
476	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
477	// 调用方必须持有 openMu。
478	func tryEvict(path string, reg *registryEntry) {
479		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
480			delete(openRegistry, path)
481		}
482	}
483	
484	var (
485		openMu       sync.Mutex
486		openRegistry = map[string]*registryEntry{}
487	)
488	
489	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
490	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
491	func Open(path string) (*Ledger, error) {
492		abs, err := filepath.Abs(path)
493		if err != nil {
494			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
495		}
496		abs = canonicalLedgerPath(abs)
497	
498		openMu.Lock()
499		defer openMu.Unlock()
500	
501		if reg := openRegistry[abs]; reg != nil {
502			reg.refs++
503			return &Ledger{path: abs, reg: reg, open: true}, nil
504		}
505	
506		data, err := os.ReadFile(abs)
507		if err != nil {
508			if errors.Is(err, os.ErrNotExist) {
509				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
510			}
511			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
512		}
513		if len(bytes.TrimSpace(data)) == 0 {
514			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
515		}
516		dec := json.NewDecoder(bytes.NewReader(data))
517		var rawDoc json.RawMessage
518		if err := dec.Decode(&rawDoc); err != nil {
519			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
520		}
521		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
522		if tok, err := dec.Token(); err != io.EOF {
523			if err == nil {
524				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
525			}
526			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
527		}
528		state, err := decodeState(rawDoc)
529		if err != nil {
530			return nil, err
531		}
532	
533		reg := &registryEntry{state: state, refs: 1}
534		openRegistry[abs] = reg
535		return &Ledger{path: abs, reg: reg, open: true}, nil
536	}
537	
538	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
539	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
540	// 从磁盘重新加载而丢失正在写入的状态。
541	func (l *Ledger) Close() error {
542		openMu.Lock()
543		defer openMu.Unlock()
544		if !l.open {
545			return nil
546		}
547		l.open = false
548		l.reg.refs--
549		tryEvict(l.path, l.reg)
550		return nil
551	}
552	
553	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
554	func (l *Ledger) beginOp() error {
555		openMu.Lock()
556		defer openMu.Unlock()
557		if !l.open {
558			return ledgerError(ErrClosed, "ledger handle is closed")
559		}
560		l.reg.ops++
561		return nil
562	}
563	
564	func (l *Ledger) endOp() {
565		openMu.Lock()
566		defer openMu.Unlock()
567		l.reg.ops--
568		tryEvict(l.path, l.reg)
569	}
570	
571	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
572	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
573	// 拆成商和余数两部分即可在 int64 内精确完成。
574	func feeFor(amount int64, feeBps int) int64 {
575		hi := amount / 10000
576		lo := amount % 10000
577		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
578	}
579	
580	func validateIntent(it PaymentIntent) (int64, string, bool) {
581		if it.ID == "" {
582			return 0, reasonEmptyID, false
583		}
584		if it.Account == "" {
585			return 0, reasonEmptyAccount, false
586		}
587		if it.Asset == "" {
588			return 0, reasonEmptyAsset, false
589		}
590		if it.Amount == nil || *it.Amount <= 0 {
591			return 0, reasonBadAmount, false
592		}
593		return *it.Amount, "", true
594	}
595	
596	// validateLimits 校验本次提交的扣款上限：账户与资产必须非空，同一组合不得重复，
597	// max_charged 必须明确提供且为非负 int64。任一不合法则整个批次拒绝（ErrInvalid），
598	// 与意图列表是否为空无关。合法时返回按组合索引的上限表；无上限时返回 nil。
599	func validateLimits(limits []ChargeLimit) (map[balanceKey]int64, error) {
600		if len(limits) == 0 {
601			return nil, nil
602		}
603		out := make(map[balanceKey]int64, len(limits))
604		for i, l := range limits {
605			if l.Account == "" {
606				return nil, ledgerError(ErrInvalid, "limit %d: account must not be empty", i)
607			}
608			if l.Asset == "" {
609				return nil, ledgerError(ErrInvalid, "limit %d: asset must not be empty", i)
610			}
611			if l.MaxCharged == nil {
612				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be provided", i, l.Account, l.Asset)
613			}
614			if *l.MaxCharged < 0 {
615				return nil, ledgerError(ErrInvalid, "limit %d (%s/%s): max_charged must be non-negative, got %d", i, l.Account, l.Asset, *l.MaxCharged)
616			}
617			k := balanceKey{l.Account, l.Asset}
618			if _, dup := out[k]; dup {
619				return nil, ledgerError(ErrInvalid, "limit %d: duplicate entry for %s/%s", i, l.Account, l.Asset)
620			}
621			out[k] = *l.MaxCharged
622		}
623		return out, nil
624	}
625	
626	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
627	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
628	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
629	//
630	// 若批次携带 limits，则每个列出的 (账户, 资产) 组合在本次提交内的成功扣款
631	// 累计（含手续费）不得超过其 max_charged：超限的项返回 limit_exceeded，
632	// 不扣余额、不留记录、不占编号与额度；未列出的组合不限制。额度按本次提交
633	// 从零计算，只有成功落账的扣款消耗额度，历史扣款与退款均不计入。
634	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
635		if err := l.beginOp(); err != nil {
636			return nil, err
637		}
638		defer l.endOp()
639		limits, err := validateBatch(batch)
640		if err != nil {
641			return nil, err
642		}
643	
644		l.reg.mu.Lock()
645		defer l.reg.mu.Unlock()
646	
647		results := l.runBatch(batch, limits, l.reg.state, true)
648		return &BatchResult{Results: results}, nil
649	}
650	
651	// Preview 在不写入账本的前提下，按当前账本预计算一个批次的结算结果，
652	// 语义与 Submit 逐项一致（状态、失败原因、结算记录格式均相同）：
653	//   - 后项看到前项“预计成功”后的可用余额与本批次已用限额；
654	//   - 预计成功的新付款使用从当前最大付款序号之后连续递增的序号，
655	//     失败、重复、冲突不消耗序号；
656	//   - 已有成功编号仍按原付款字段与费率判断重复或冲突（原付款已退款也一样），
657	//     重复项携带原记录，不占余额与本批次额度；本批次首次预计成功的编号对
658	//     后续项同样生效（相同请求重复、字段不同冲突），失败项不占编号；
659	//   - 手续费、金额溢出、状态与限额判断沿用实际提交规则，同时超限与余额不足
660	//     仍先报告超限，限额只累计本次预计成功的扣款（含手续费）。
661	//
662	// 预览全程在当前状态的深拷贝上进行：不持久化、不修改真实余额与历史，
663	// 任何编号、序号和额度都不被预留；连续预览相同批次（账本未变化）结果一致，
664	// 随后真实提交仍按首次提交处理。预览只预测业务结果，不承诺真实提交时的
665	// 写入成功（因此预览结果中不会出现 storage_error）。费率或限额非法属于
666	// 批次级错误，返回 invalid_parameter 且不产生部分结果（空批次同样检查）。
667	func (l *Ledger) Preview(batch FeeBatch) (*PreviewResult, error) {
668		if err := l.beginOp(); err != nil {
669			return nil, err
670		}
671		defer l.endOp()
672		limits, err := validateBatch(batch)
673		if err != nil {
674			return nil, err
675		}
676	
677		l.reg.mu.Lock()
678		defer l.reg.mu.Unlock()
679	
680		// 在快照副本上模拟：预览结束后真实状态与磁盘文件保持原样。
681		sim := cloneState(l.reg.state)
682		results := l.runBatch(batch, limits, sim, false)
683		return &PreviewResult{DryRun: true, Results: results}, nil
684	}
685	
686	// validateBatch 执行批次级校验：费率范围与本次扣款上限。任一不合法都返回
687	// 批次级错误（invalid_parameter），调用方不得执行任何意图（空批次同样检查）。
688	func validateBatch(batch FeeBatch) (map[balanceKey]int64, error) {
689		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
690			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
691		}
692		// 限额非法是批次级错误：任何意图都不执行（空意图列表同样检查）。
693		return validateLimits(batch.Limits)
694	}
695	
696	// runBatch 按输入顺序在给定状态 st 上处理整个批次，返回逐项结果。
697	// persist 为 true 时（真实提交）每笔预计成功都先写入 st 再原子落盘，
698	// 落盘失败回滚该项并报告 storage_error；为 false 时（预览）只在 st
699	// （应为独立副本）上推进内存状态、绝不触碰磁盘，因此不会产生存储错误。
700	// 调用方必须持有 reg.mu。
701	func (l *Ledger) runBatch(batch FeeBatch, limits map[balanceKey]int64, st *ledgerState, persist bool) []ItemResult {
702		out := make([]ItemResult, 0, len(batch.Intents))
703	
704		// 本次批次内各组合已消耗的额度，从零开始，仅预计成功的扣款计入。
705		used := make(map[balanceKey]int64, len(limits))
706	
707		for i := range batch.Intents {
708			it := &batch.Intents[i]
709			res := ItemResult{ID: it.ID}
710	
711			// 1. 参数校验。未通过的编号不占用去重资格。
712			amount, reason, ok := validateIntent(*it)
713			if !ok {
714				res.Status = StatusInvalid
715				res.Reason = reason
716				out = append(out, res)
717				continue
718			}
719	
720			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
721			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
722			//    本批次内先（预计）成功的同编号项也在此被看到。
723			if rec, exists := findRecordIn(st.Settlements, it.ID); exists {
724				if sameRequest(rec, it, amount, batch.FeeBps) {
725					cp := rec
726					res.Status = StatusDuplicate
727					res.Reason = reasonDuplicate
728					res.Record = &cp
729				} else {
730					res.Status = StatusConflict
731					res.Reason = reasonConflict
732				}
733				out = append(out, res)
734				continue
735			}
736	
737			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
738			if it.State != "" && it.State != "pending" {
739				res.Status = StatusState
740				res.Reason = reasonNotPending
741				out = append(out, res)
742				continue
743			}
744	
745			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
746			fee := feeFor(amount, batch.FeeBps)
747			if fee > math.MaxInt64-amount {
748				res.Status = StatusInvalid
749				res.Reason = reasonOverflow
750				out = append(out, res)
751				continue
752			}
753			total := amount + fee
754	
755			key := balanceKey{it.Account, it.Asset}
756	
757			// 5. 本次批次限额（先于余额判断：同时超限与余额不足时报告超限）。
758			//    恰好达到上限仍允许；用 total > max-used 而非 used+total > max，
759			//    避免累计接近 int64 上界时溢出放行。失败不消耗额度。
760			if max, capped := limits[key]; capped {
761				if u := used[key]; total > max-u {
762					res.Status = StatusLimitExceeded
763					res.Reason = fmt.Sprintf(reasonLimitExceeded, it.Account, it.Asset, max, u, total)
764					out = append(out, res)
765					continue
766				}
767			}
768	
769			// 6. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
770			bal := st.Balances[key]
771			if total > bal {
772				res.Status = StatusFunds
773				res.Reason = reasonFunds
774				out = append(out, res)
775				continue
776			}
777	
778			// 7. 预计成功：构造记录（序号按当前模拟历史长度连续递增）。
779			rec := Record{
780				ID:        it.ID,
781				Account:   it.Account,
782				Paymaster: it.Paymaster,
783				Asset:     it.Asset,
784				Amount:    amount,
785				Nonce:     it.Nonce,
786				FeeBps:    batch.FeeBps,
787				Fee:       fee,
788				Charged:   total,
789				Seq:       int64(len(st.Settlements)) + 1,
790			}
791	
792			if persist {
793				// 真实提交：先在内存生效，再原子持久化；保存失败回滚该项，
794				// 不留成功记录、不占额度。
795				rollback := stageOn(st, key, bal-total, rec)
796				if err := l.persistLocked(); err != nil {
797					rollback()
798					res.Status = StatusStorage
799					res.Reason = err.Error()
800					out = append(out, res)
801					continue
802				}
803			} else {
804				// 预览：只推进副本状态，绝不落盘。
805				st.Balances[key] = bal - total
806				st.Settlements = append(st.Settlements, rec)
807			}
808	
809			// 只有（预计）成功的扣款消耗额度；预览同样如此。
810			used[key] += total
811			cp := rec
812			res.Status = StatusSettled
813			res.Record = &cp
814			out = append(out, res)
815		}
816		return out
817	}
818	
819	// cloneState 返回账本状态的独立深拷贝，供预览在副本上模拟而不触碰真实状态。
820	func cloneState(st *ledgerState) *ledgerState {
821		cp := &ledgerState{
822			Version:     st.Version,
823			Initial:     make(map[balanceKey]int64, len(st.Initial)),
824			Balances:    make(map[balanceKey]int64, len(st.Balances)),
825			Settlements: append([]Record(nil), st.Settlements...),
826			Refunds:     append([]RefundRecord(nil), st.Refunds...),
827		}
828		for k, v := range st.Initial {
829			cp.Initial[k] = v
830		}
831		for k, v := range st.Balances {
832			cp.Balances[k] = v
833		}
834		return cp
835	}
836	
837	// findRecordIn 在给定结算历史中按编号查找成功记录。
838	func findRecordIn(records []Record, id string) (Record, bool) {
839		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
840		for _, r := range records {
841			if r.ID == id {
842				return r, true
843			}
844		}
845		return Record{}, false
846	}
847	
848	// stageOn 在指定状态上应用一笔扣款与记录，返回回滚函数（恢复该项执行前的
849	// 余额与记录长度）。
850	func stageOn(st *ledgerState, key balanceKey, newBal int64, rec Record) func() {
851		oldBal, hadKey := st.Balances[key]
852		oldLen := len(st.Settlements)
853		st.Balances[key] = newBal
854		st.Settlements = append(st.Settlements, rec)
855		return func() {
856			if hadKey {
857				st.Balances[key] = oldBal
858			} else {
859				delete(st.Balances, key)
860			}
861			st.Settlements = st.Settlements[:oldLen]
862		}
863	}
864	
865	// Refund 按输入顺序处理一个退款批次。各项独立处理：后项能看到前项成功退回的
866	// 余额；任一项失败不影响其余项（存储错误只回滚出错项本身，前项保留，后项继续）。
867	// 结果与输入逐项对应，空批次返回空结果。
868	//
869	// 语义：
870	//   - 参数合法时，已成功的退款编号优先判定：目标结算与原因都相同返回 duplicate
871	//     及原退款记录（不再入账）；任一不同返回 conflict。
872	//   - 新退款编号：找不到成功结算（含原付款只曾失败）返回 not_found；
873	//     该结算已被其他退款编号退回返回 refunded，不增加余额。
874	//   - 成功时把原记录的 charged（含当时已扣手续费）全额退回原账户、原资产；
875	//     退款金额与去向完全由原结算确定，原结算记录及其编号、顺序保持不变。
876	//   - 失败申请不占用退款编号，之后可修改原因或目标再提交。
877	func (l *Ledger) Refund(batch RefundBatch) (*RefundBatchResult, error) {
878		if err := l.beginOp(); err != nil {
879			return nil, err
880		}
881		defer l.endOp()
882		out := &RefundBatchResult{Results: make([]RefundResult, 0, len(batch.Refunds))}
883	
884		l.reg.mu.Lock()
885		defer l.reg.mu.Unlock()
886	
887		for i := range batch.Refunds {
888			req := &batch.Refunds[i]
889			res := RefundResult{ID: req.ID}
890	
891			// 1. 参数校验：退款编号、原付款编号、原因三者都必须非空。
892			//    未通过的编号不占用退款资格。
893			if req.ID == "" {
894				res.Status = StatusInvalid
895				res.Reason = reasonEmptyRefundID
896				out.Results = append(out.Results, res)
897				continue
898			}
899			if req.SettlementID == "" {
900				res.Status = StatusInvalid
901				res.Reason = reasonEmptySettlement
902				out.Results = append(out.Results, res)
903				continue
904			}
905			if req.Reason == "" {
906				res.Status = StatusInvalid
907				res.Reason = reasonEmptyReason
908				out.Results = append(out.Results, res)
909				continue
910			}
911	
912			// 2. 已成功退款编号优先判定：目标与原因都相同则幂等返回原退款记录；
913			//    任一不同则冲突。两者都不再入账。本批次内先成功的同编号项也在此可见。
914			if prior, exists := l.findRefund(req.ID); exists {
915				if prior.SettlementID == req.SettlementID && prior.Reason == req.Reason {
916					cp := prior
917					res.Status = StatusDuplicate
918					res.Reason = prior.Reason
919					res.SettlementID = prior.SettlementID
920					res.Account = prior.Account
921					res.Asset = prior.Asset
922					res.Charged = prior.Charged
923					res.Record = &cp
924				} else {
925					res.Status = StatusConflict
926					res.Reason = reasonRefundConflict
927				}
928				out.Results = append(out.Results, res)
929				continue
930			}
931	
932			// 3. 新退款编号：目标必须是一笔成功结算（原付款只曾失败也算不存在）。
933			target, exists := l.findRecord(req.SettlementID)
934			if !exists {
935				res.Status = StatusNotFound
936				res.Reason = fmt.Sprintf(reasonSettlementGone, req.SettlementID)
937				out.Results = append(out.Results, res)
938				continue
939			}
940	
941			// 4. 每笔原付款最多退回一次：已被其他退款编号退回则报告已退款，不加余额。
942			if prior, refunded := l.findRefundOfSettlement(req.SettlementID); refunded {
943				res.Status = StatusAlreadyRefunded
944				res.Reason = fmt.Sprintf(reasonAlreadyRefunded, req.SettlementID, prior.ID)
945				out.Results = append(out.Results, res)
946				continue
947			}
948	
949			// 5. 全额退回原账户、原资产（amount 与当时手续费一并退回），
950			//    与退款记录在同一个原子写入中落盘；保存失败回滚该项。
951			rec := RefundRecord{
952				ID:           req.ID,
953				SettlementID: target.ID,
954				Reason:       req.Reason,
955				Account:      target.Account,
956				Asset:        target.Asset,
957				Amount:       target.Amount,
958				Fee:          target.Fee,
959				Charged:      target.Charged,
960				AfterSeq:     int64(len(l.reg.state.Settlements)),
961				Seq:          int64(len(l.reg.state.Refunds)) + 1,
962			}
963			key := balanceKey{target.Account, target.Asset}
964			bal := l.reg.state.Balances[key]
965			rollback := l.stageRefund(key, bal+target.Charged, rec)
966			if err := l.persistLocked(); err != nil {
967				rollback()
968				res.Status = StatusStorage
969				res.Reason = err.Error()
970			} else {
971				cp := rec
972				res.Status = StatusRefundSuccess
973				res.Reason = rec.Reason
974				res.SettlementID = rec.SettlementID
975				res.Account = rec.Account
976				res.Asset = rec.Asset
977				res.Charged = rec.Charged
978				res.Record = &cp
979			}
980			out.Results = append(out.Results, res)
981		}
982		return out, nil
983	}
984	
985	// stageRefund 应用一笔退款（余额增加 + 记录追加），返回回滚函数。
986	func (l *Ledger) stageRefund(key balanceKey, newBal int64, rec RefundRecord) func() {
987		oldBal, hadKey := l.reg.state.Balances[key]
988		oldLen := len(l.reg.state.Refunds)
989		l.reg.state.Balances[key] = newBal
990		l.reg.state.Refunds = append(l.reg.state.Refunds, rec)
991		return func() {
992			if hadKey {
993				l.reg.state.Balances[key] = oldBal
994			} else {
995				delete(l.reg.state.Balances, key)
996			}
997			l.reg.state.Refunds = l.reg.state.Refunds[:oldLen]
998		}
999	}
1000	
1001	func (l *Ledger) findRefund(id string) (RefundRecord, bool) {
1002		// 退款按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
1003		for _, r := range l.stateView().Refunds {
1004			if r.ID == id {
1005				return r, true
1006			}
1007		}
1008		return RefundRecord{}, false
1009	}
1010	
1011	// findRefundOfSettlement 返回退回指定结算的那笔退款（每笔结算最多一笔）。
1012	func (l *Ledger) findRefundOfSettlement(settlementID string) (RefundRecord, bool) {
1013		for _, r := range l.stateView().Refunds {
1014			if r.SettlementID == settlementID {
1015				return r, true
1016			}
1017		}
1018		return RefundRecord{}, false
1019	}
1020	
1021	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
1022	
1023	func (l *Ledger) findRecord(id string) (Record, bool) {
1024		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
1025		for _, r := range l.stateView().Settlements {
1026			if r.ID == id {
1027				return r, true
1028			}
1029		}
1030		return Record{}, false
1031	}
1032	
1033	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
1034	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
1035		return r.Account == it.Account &&
1036			r.Paymaster == it.Paymaster &&
1037			r.Asset == it.Asset &&
1038			r.Amount == amount &&
1039			r.Nonce == it.Nonce &&
1040			r.FeeBps == feeBps
1041	}
1042	
1043	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
1044	func (l *Ledger) Query() (*Snapshot, error) {
1045		if err := l.beginOp(); err != nil {
1046			return nil, err
1047		}
1048		defer l.endOp()
1049		l.reg.mu.Lock()
1050		defer l.reg.mu.Unlock()
1051	
1052		st := l.stateView()
1053		bals := make([]BalanceView, 0, len(st.Balances))
1054		for k, v := range st.Balances {
1055			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
1056		}
1057		sortBalances(bals)
1058		recs := make([]Record, len(st.Settlements))
1059		copy(recs, st.Settlements)
1060		refunds := make([]RefundRecord, len(st.Refunds))
1061		copy(refunds, st.Refunds)
1062		return &Snapshot{Balances: bals, Settlements: recs, Refunds: refunds}, nil
1063	}
1064	
1065	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
1066	func (l *Ledger) Balance(account, asset string) (int64, error) {
1067		if err := l.beginOp(); err != nil {
1068			return 0, err
1069		}
1070		defer l.endOp()
1071		l.reg.mu.Lock()
1072		defer l.reg.mu.Unlock()
1073		return l.stateView().Balances[balanceKey{account, asset}], nil
1074	}
1075	
1076	func sortBalances(bals []BalanceView) {
1077		sort.Slice(bals, func(i, j int) bool {
1078			if bals[i].Account != bals[j].Account {
1079				return bals[i].Account < bals[j].Account
1080			}
1081			return bals[i].Asset < bals[j].Asset
1082		})
1083	}
1084	
1085	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
1086	func (l *Ledger) persistLocked() error {
1087		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
1088			return ledgerError(ErrStorage, "injected write failure")
1089		}
1090		return atomicWrite(l.path, l.stateView())
1091	}
1092	
1093	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
1094	func SetFailHook(l *Ledger, fw FailWriter) {
1095		l.reg.failHook = fw
1096	}
1097

