func TestPreviewLedgerErrors(t *testing.T) {
	missing := filepath.Join(t.TempDir(), "nope.json")
	if _, err := Open(missing); KindOf(err) != ErrNotInit {
		t.Fatalf("missing ledger: %v", err)
	}
