		bal := st.Balances[key]
		if total > bal {
			res.Status = StatusFunds
			res.Reason = reasonFunds
			out = append(out, res)
			continue
		}

		// 7. 预计成功：构造记录（序号按当前模拟历史长度连续递增）。
		rec := Record{
			ID:        it.ID,
			Account:   it.Account,
			Paymaster: it.Paymaster,
			Asset:     it.Asset,
			Amount:    amount,
			Nonce:     it.Nonce,
			FeeBps:    batch.FeeBps,
			Fee:       fee,
			Charged:   total,
			Seq:       int64(len(st.Settlements)) + 1,
		}

